head.script:

	// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
		//JSON 형태의 2건의 list data를 set.
		var tmpArr = [{"col1":"철수 & 영희","col2":"철수 & 영희","col3":""}];
		dataList1.setJSON( tmpArr );
	};

	scwin.onpageunload = function() {

	};


	scwin.fireOver = function(node) {
		if (document.createEventObject) {
			node.fireEvent('onmouseover');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('mouseover', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.onmouseover == 'function') {
			node.onmouseover();
		}
	}
	scwin.fireOut = function(node) {
		if (document.createEventObject) {
			node.fireEvent('onmouseout');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('mouseout', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.onmouseout == 'function') {
			node.onmouseout();
		}
	}	
	scwin.mouseOverBehaviour = function(id) {
		var el = scwin.__getDom($p.id + id);
		scwin.fireOver(el);
	}
	scwin.mouseOutBehaviour = function(id) {
		var el = scwin.__getDom($p.id + id);
		scwin.fireOut(el);
	}	
	scwin.checkVal = function() {
		const tooltipElement = (document.getElementById('grd_list_tooltip') || document.getElementById('mf_grd_list_tooltip'));
		let reVal = false;

		if (tooltipElement) {
			let displayValue = tooltipElement.style.display;
			console.log('tooltip 요소의 display 값:', displayValue);
			reVal = (document.getElementById('grd_list_tooltip') || document.getElementById('mf_grd_list_tooltip')).style.display != 'block';
		} else {
			console.log('요소가 존재하지 않음: grd_list_tooltip');
			reVal = true;
		}
		return reVal;
	}		
	scwin.checkVal = function() {
		return (document.getElementById('wq_uuid_3_tooltip') || document.getElementById('mf_wq_uuid_3_tooltip')).innerText == '철수 & 영희';
	}
